import io,re
FILES=['public/viewer.js','public/index.html','server.js']
BANNED=r'\b(simply|obviously|clearly|basically|essentially|needless to say|note that)\b'
US=r'\b(color|center|normalize|behavior|gray|catalog|traveled)\b'
bad=[]
for p in FILES:
    try: txt=io.open(p,encoding='utf-8').read()
    except IOError: continue
    for i,l in enumerate(txt.splitlines(),1):
        s=l.strip()
        seg=s if s.startswith(('//','<!--','/*','*')) else (l.split('//',1)[1] if ('//' in l and not re.search(r'https?://',l)) else None)
        if not seg: continue
        t=seg.rstrip()
        if any(ord(c)>127 for c in seg): bad.append((p,i,'non-ascii',t[:50]))
        if t.endswith('.') and not re.search(r'\.\.$|e\.g\.$|i\.e\.$',t): bad.append((p,i,'trailing period',t[-45:]))
        if re.search(BANNED,t,re.I): bad.append((p,i,'banned word',t[:50]))
        if re.search(US,t): bad.append((p,i,'us spelling',t[:50]))
print('\n'.join(map(str,bad)) if bad else 'clean')
PY
